<?php
require_once __DIR__.'/../../includes/auth.php';requireSuperAdmin();require_once __DIR__.'/../../includes/functions.php';
$sessions=$pdo->query("SELECT u.*,e.name event_name,x.full_name contestant_name FROM ussd_sessions u LEFT JOIN events e ON e.id=u.event_id LEFT JOIN contestants x ON x.id=u.selected_contestant_id ORDER BY COALESCE(u.last_activity_at,u.started_at) DESC LIMIT 200")->fetchAll();
$active=$completed=$expired=0;foreach($sessions as $s){if($s['status']==='Active')$active++;elseif($s['status']==='Completed')$completed++;elseif($s['status']==='Expired')$expired++;}
$pageTitle='USSD Monitor';require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/sidebar.php';?><main class="main"><?php require __DIR__.'/../../includes/topbar.php';?><section class="content"><div class="d-flex justify-content-between align-items-end mb-4"><div><span class="section-kicker">USSD OPERATIONS</span><h1 class="page-title">USSD Monitor</h1><p class="page-subtitle">Arkesel sessions and the current VoteHub voting state.</p></div><a href="<?=APP_URL?>/admin/ussd-simulator.php" class="btn btn-primary"><i class="bi bi-phone me-1"></i>Open Simulator</a></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="card-box stat"><div class="stat-label">Active</div><div class="stat-value"><?=$active?></div></div></div><div class="col-md-4"><div class="card-box stat"><div class="stat-label">Completed</div><div class="stat-value"><?=$completed?></div></div></div><div class="col-md-4"><div class="card-box stat"><div class="stat-label">Expired</div><div class="stat-value"><?=$expired?></div></div></div></div><div class="panel"><div class="panel-head"><h5>Recent Sessions</h5><small class="text-muted">Refresh the page for latest activity</small></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Session</th><th>Phone</th><th>Network</th><th>Step</th><th>Event</th><th>Contestant</th><th>Status</th><th>Last Activity</th></tr></thead><tbody><?php foreach($sessions as $s):?><tr><td class="font-monospace small"><?=e($s['session_id'])?></td><td><?=e($s['phone_number'])?></td><td><?=e($s['network']??'')?></td><td><?=e($s['current_step'])?></td><td><?=e($s['event_name']??'')?></td><td><?=e($s['contestant_name']??'')?></td><td><?=e($s['status'])?></td><td><?=e($s['last_activity_at']??$s['started_at'])?></td></tr><?php endforeach;if(!$sessions):?><tr><td colspan="8" class="text-center py-5 text-muted">No USSD sessions recorded yet.</td></tr><?php endif;?></tbody></table></div></div></section></main><script>setTimeout(()=>location.reload(),20000)</script><?php require __DIR__.'/../../includes/footer.php';?>
